Here is an example code for calibrating a DHT22 temperature and humidity sensor using an Arduino:
```
#include <DHT.h>

// Define constants
#define DHT_PIN 2 // Pin connected to DHT22 sensor
#define CALIBRATION_TEMP 20.0 // Initial temperature value
#define CALIBRATION_HUM 40.0 // Initial humidity value

// Define variables
float dht_temp;
float dht_hum;
float calib_temp_offset;
float calib_hum_offset;

void setup() {
  // Initialize serial communication
  Serial.begin(9600);

  // Initialize DHT sensor
  DHT dht(DHT_PIN, DHT22);

  // Read initial values from DHT sensor
  dht.temp = dht.readTemperature();
  dht.hum = dht.readHumidity();

  // Calculate initial offsets
  calib_temp_offset = CALIBRATION_TEMP - dht.temp;
  calib_hum_offset = CALIBRATION_HUM - dht.hum;

  // Display initial values and offsets
  Serial.print("Initial temperature: ");
  Serial.print(dht.temp);
  Serial.print("C, ");
  Serial.print("Initial humidity: ");
  Serial.print(dht.hum);
  Serial.println("%");
  Serial.print("Initial temperature offset: ");
  Serial.print(calib_temp_offset);
  Serial.print("C");
  Serial.print("Initial humidity offset: ");
  Serial.print(calib_hum_offset);
  Serial.println("%");
}

void loop() {
  // Read values from DHT sensor
  dht.temp = dht.readTemperature();
  dht.hum = dht.readHumidity();

  // Calculate corrected values using offsets
  float corrected_temp = dht.temp + calib_temp_offset;
  float corrected_hum = dht.hum + calib_hum_offset;

  // Display corrected values
  Serial.print("Corrected temperature: ");
  Serial.print(corrected_temp);
  Serial.print("C, ");
  Serial.print("Corrected humidity: ");
  Serial.print(corrected_hum);
  Serial.println("%");

  delay(10000); // Wait 10 seconds between readings
}
```
