Here is a basic JavaScript applet that simulates a pendulum:
```
<canvas id="pendulum" width="400" height="400"></canvas>

<input id="initial-angle" type="number" value="30" />
<button id="release-button">Release</button>

<script>
  const canvas = document.getElementById('pendulum');
  const ctx = canvas.getContext('2d');

  // Pendulum parameters
  const g = 9.8; // acceleration due to gravity
  const m = 0.1; // mass of the pendulum
  const L = 100; // length of the pendulum
  const initialAngle = 30; // initial angle (in degrees)

  // User input and button
  const initialAngleInput = document.getElementById('initial-angle');
  const releaseButton = document.getElementById('release-button');

  // Pendulum state variables
  let angle = 0;
  let angularVelocity = 0;
  let time = 0;

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.beginPath();
    ctx.arc(canvas.width / 2, canvas.height / 2, L, 0, 2 * Math.PI);
    ctx.strokeStyle = 'black';
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(canvas.width / 2, canvas.height / 2, L * Math.sin(Math.degToRad(angle)), 0, 2 * Math.PI);
    ctx.strokeStyle = 'red';
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  function update() {
    // Update angular velocity
    angularVelocity += (-g / L) * Math.sin(Math.degToRad(angle));
    angularVelocity *= 0.99; // damping

    // Update angle
    angle += angularVelocity;

    // Check if pendulum has stopped
    if (Math.abs(angularVelocity) < 0.01) {
      angle = 0;
      angularVelocity = 0;
    }
  }

  function tick() {
    update();
    draw();
  }

  function Math.degToRad(deg) {
    return deg * (Math.PI / 180);
  }

  // Initialize
  initialAngle = parseFloat(initialAngleInput.value);
  time = 0;
  angle = Math.degToRad(initialAngle);
  angularVelocity = 0;

  // Main loop
  requestAnimationFrame(() => {
    tick();
    requestAnimationFrame(() => {
      tick();
    });
  });

  // Release button event handler
  releaseButton.addEventListener('click', () => {
    time = 0;
    angle = Math.degToRad(initialAngleInput.value);
    angularVelocity = 0;
  });
</script>
```
This applet uses the canvas element to draw the pendulum, and JavaScript to simulate the motion. The initial angle is set by the user input field, and the release button resets the pendulum to its initial state.

The physics is simulated using the following equations:

* Angular velocity: `dtheta/dt = -g/L * sin(theta)`
* Angle: `theta = theta0 + integral(angular_velocity dt) + C`

Where `theta0` is the initial angle, `g` is the acceleration due to gravity, `L` is the length of the pendulum, and `C` is a constant.

The applet uses a simple Euler method to update the angle and angular velocity, and a damping term to simulate the energy loss due to friction.

