#include <pigpio.h>

int main() {
  // Initialize the pigpio library
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialization failed\n");
    return 1;
  }

  // Set up GPIO pin 12 as an output
  gpioSetup(12, PI_OUTPUT);

  // Set GPIO pin 12 high (on)
  gpioWrite(12, PI_HIGH);

  // Wait for 2 seconds
  sleep(2);

  // Set GPIO pin 12 low (off)
  gpioWrite(12, PI_LOW);

  // Clean up
  gpioTerminate();

  return 0;
}
